package iso.tool;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class DependencyDetector {
 public static final class Dependency {public String name;public List<String> commands;public boolean required;public String category,path,status,version;Dependency(String n,List<String> c,boolean r,String k){name=n;commands=c;required=r;category=k;status="missing";}}
 private static Dependency d(String n,boolean r,String k,String... c){return new Dependency(n,Arrays.asList(c),r,k);}
 public static List<Dependency> detect(){List<Dependency> a=Arrays.asList(d("git",true,"source","git"),d("python",true,"runtime","python","python3"),d("cmake",true,"build","cmake"),d("gcc",false,"compiler","gcc"),d("g++",false,"compiler","g++"),d("msvc",false,"compiler","cl"),d("clang",false,"compiler","clang"),d("lld",false,"linker","lld"),d("nasm",false,"assembler","nasm"),d("masm",false,"assembler","ml","ml64"),d("ninja",false,"build","ninja"),d("msbuild",false,"build","msbuild"),d("xorriso",false,"image","xorriso","xorrisofs"),d("oscdimg",false,"image","oscdimg"),d("qemu",false,"verification","qemu-system-x86_64"),d("java",false,"runtime","java"),d("javac",false,"compiler","javac"),d("dotnet",false,"runtime","dotnet"),d("node",false,"runtime","node"),d("go",false,"compiler","go"),d("rustc",false,"compiler","rustc"),d("7zip",false,"archive","7z","7zz"));for(Dependency x:a){for(String c:x.commands){try{Process p=new ProcessBuilder(c,"--version").redirectErrorStream(true).start();x.status="found";x.path=c;BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));x.version=r.readLine();p.destroy();break;}catch(Exception ignored){}}}return a;}
 public static void write(Path file)throws IOException{Files.createDirectories(file.getParent());StringBuilder s=new StringBuilder("{\"dependencies\":[");List<Dependency>a=detect();for(int i=0;i<a.size();i++){if(i>0)s.append(',');Dependency d=a.get(i);s.append("{\"name\":\"").append(d.name).append("\",\"required\":").append(d.required).append(",\"category\":\"").append(d.category).append("\",\"status\":\"").append(d.status).append("\",\"path\":\"").append(d.path==null?"":d.path).append("\"}");}s.append("]}");Files.write(file,s.toString().getBytes("UTF-8"));}
}
